// CSD_RATIONALE_BEGIN
// This strategy solves math word problems by generating ordinary explanatory
// text outside constrained spans and symbolic expressions inside visible "<<"
// ... ">>" spans. It tracks the usual visible output state plus the active
// constrained prefix. Outside spans it uses short unconstrained chunks so the
// model can naturally reach an opening delimiter; if a math cue such as "=" or
// "answer" appears in recent text, it may proactively open a constrained span.
// Inside spans it chooses between token-level and small multi-token symbolic
// progress based on parser narrowness and remaining token budget, while using
// caller-supplied token groups and lightweight repetition/context preferences
// to bias legal choices. If the constrained prefix becomes too dead-ended, it
// rolls back the constrained suffix to a valid prefix and continues.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span chunk branch, insideConstrainedOut stays
//   false unless an observed "<<" is entered with EnterObservedConstrainedSpan,
//   which resets currentConstrainedOut to [] and therefore preserves validity.
//   In the proactive-open branch, OpenConstrainedSpan likewise sets a fresh []
//   constrained prefix. In the close branch, CloseConstrainedSpan exits the
//   span so the implication becomes vacuous. In the rollback branch,
//   RollbackConstrainedSuffix returns a repaired parser-valid constrained
//   prefix. In the one-token constrained branches, the chosen helper returns
//   EOS or a parser-valid next token, and AppendConstrainedToken preserves
//   parser validity. In the symbol branch, ConstrainedSymbolInGenerated
//   returns a longest valid constrained prefix, so validity is preserved.
// progress: UnconstrainedChunk consumes stepsUsed token-steps and appends at
//   most that many visible tokens; if it stopped on EOS, EOS counts in
//   stepsUsed but is not appended, so the bound still holds. OpenConstrainedSpan
//   and CloseConstrainedSpan each consume one step and append at most one
//   delimiter token. RollbackConstrainedSuffix may shrink visible output and
//   consumes no LM tokens, but we charge one loop step for repair, so the bound
//   remains true. Each one-token constrained helper consumes one token-step and
//   AppendConstrainedToken appends at most one visible token. The symbol branch
//   advances steps by stepsUsed, and visible growth is at most the accepted
//   constrained-prefix growth, which is bounded by the consumed token budget
//   even when some sampled suffix tokens or EOS are not appended.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var cueArmed: bool := false;
var recentAfterAnswer: seq<Token> := helpers.ExtractAfterKeyword(generated, "answer");
var flatGroups: seq<Token> := helpers.FlattenTokenGroups(validTokenGroups);

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if cueArmed {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      cueArmed := false;
      steps := steps + 1;
    } else {
      var remainingChunk: nat := maxSteps - steps;
      var chunkBudget: nat := if remainingChunk <= 2 then remainingChunk else 2;
      var chunkedGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
        lm, prompt, generated, chunkBudget, "<<", eosToken
      );
      generated := chunkedGenerated;
      steps := steps + stepsUsed;
      recentAfterAnswer := helpers.ExtractAfterKeyword(generated, "answer");
      if stoppedOnEos {
        break;
      } else if stoppedOnOpenSpan {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
        cueArmed := false;
      } else {
        var prevTok, foundPrev := helpers.LastTokenBefore(generated, ">>");
        cueArmed := false;
        if foundPrev && (prevTok == "=" || prevTok == ":" || prevTok == "is") {
          cueArmed := true;
        } else if |recentAfterAnswer| > 0 {
          cueArmed := true;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    recentAfterAnswer := helpers.ExtractAfterKeyword(generated, "answer");
    cueArmed := false;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= 24 && helpers.DeadEndDetection(parser, currentConstrainedOut, 1) {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
    var remaining: nat := maxSteps - steps;

    if remaining >= 2 && stepTokenBudget > 1 && validCount > 8 {
      var symbolBudget: nat := if stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      currentConstrainedOut := symbolOut;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    } else {
      var preferred: seq<Token> := flatGroups;
      if |recentAfterAnswer| > 0 {
        preferred := helpers.IntersectTokenSets(flatGroups, recentAfterAnswer);
      }
      var penalized := helpers.SubtractTokenSets(generated, preferred);

      var next := eosToken;
      if validCount <= 3 {
        next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      } else if |preferred| > 0 {
        next := helpers.SafeBoostedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, preferred, 4.0, eosToken
        );
      } else if |penalized| > 0 {
        next := helpers.SafePenalizedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, penalized, 2.0, eosToken
        );
      } else if validCount <= 12 {
        next := helpers.AdaptiveConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
        );
      } else {
        next := helpers.ConfidenceGatedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken).0;
      }

      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }
}

cost := steps;

